from h import *
P=[]
P.append(R(3714,"Pasta dengan Kembang Kol","Pasta dengan Kembang Kol adalah resep sehat, mudah, dan ramah ginjal untuk disajikan pada acara kumpul berikutnya.","8","1 cangkir pasta dengan 1/2 cangkir saus kembang kol",
["1 kepala kembang kol sedang","2 sendok makan minyak zaitun","1 bawang bombai sedang","3 siung bawang putih","1/4 sendok teh lada hitam","1/4 sendok teh cabai merah tumbuk","14 ons kaldu ayam rendah natrium","16 ons linguine gandum utuh, mentah","8 sendok makan keju Parmesan parut","2 sendok makan peterseli segar"],
["Cuci kembang kol dan potong menjadi potongan seukuran suapan. Cincang halus bawang bombai dan cincang halus bawang putih.","Panaskan minyak zaitun dalam panci besar dengan api sedang. Masukkan bawang bombai dan bawang putih lalu tumis sekitar 5 menit hingga bawang bombai bening.","Tambahkan kembang kol, lada hitam, dan cabai merah lalu tumis selama 5 menit.","Tambahkan kaldu ayam dan didihkan. Kecilkan api dan biarkan kembang kol matang hingga empuk.","Masak linguine sesuai petunjuk kemasan, tanpa garam. Tiriskan dan kembalikan ke panci yang digunakan untuk memasaknya. Tambahkan beberapa sendok kaldu dari campuran kembang kol ke linguine dan aduk agar tidak lengket.","Bagi linguine menjadi 8 porsi individu dan beri topping kembang kol dan kaldu.","Tambahkan 1 sendok makan keju Parmesan parut dan lebih banyak lada hitam dan merah sesuai selera. Cincang peterseli dan taburkan merata sebagai hiasan di setiap porsi."],
["Batasi keju Parmesan hingga 1 sendok makan per porsi agar fosfor tetap rendah."],
["3 pati","1/2 daging","1 sayuran, kalium rendah"]))
P.append(R(3716,"Bumbu Meksiko","Bumbu Meksiko adalah resep ramah ginjal yang dapat digunakan pada daging sapi, ayam, atau makanan laut.","8","1 sendok teh",
["3 sendok teh bubuk cabai","2 sendok teh paprika","2 sendok teh jinten bubuk","1 sendok teh bubuk bawang bombai","1/2 sendok teh bubuk bawang putih","1/8 sendok teh cabai cayenne"],
["Campurkan rempah-rempah dalam botol kecil atau mangkuk.","Simpan dalam botol atau wadah tertutup hingga 6 bulan.","Gunakan untuk membumbui daging atau sayuran untuk taco, fajita, atau burrito."],
["Gunakan sebagai bumbu lumur kering, tambahkan ke krim asam atau yogurt Yunani untuk membuat dip, atau bumbui dressing salad buatan sendiri favorit Anda.","Sesuaikan cabai cayenne dengan selera Anda."],
["tidak ada"]))
P.append(R(3720,"Kubis Caraway dan Nasi","Ahli gizi ginjal DaVita, Sara dari California, membagikan Kubis Caraway dengan Nasi, resep rendah natrium dan ramah ginjal yang renyah, lezat, dan sehat.","2","1 cangkir",
["Semprotan masak antilengket","1 cangkir kubis","1 sendok makan bawang bombai","1/4 cangkir air","1 sendok makan saus Worcestershire","1/2 sendok teh biji caraway","1/4 cangkir jeruk mandarin kalengan","1 cangkir nasi, matang"],
["Iris halus kubis dan cincang bawang bombai.","Semprot wajan antilengket dengan semprotan masak dan tumis bawang bombai dan kubis hingga layu.","Tambahkan air, saus Worcestershire, dan biji caraway. Masak selama 3 menit. Aduk agar tidak gosong.","Tiriskan jeruk mandarin dan tambahkan ke campuran kubis. Masukkan nasi panas dan aduk.","Angkat dari api dan sajikan."],
["Gunakan campuran coleslaw sebagai pengganti kubis jika diinginkan."],
["1 pati","1 sayuran, kalium sedang","1/2 kalori tinggi"]))
P.append(R(3725,"Dressing Ranch","Cobalah resep Dressing Ranch yang ramah ginjal ini dan Anda tidak akan pernah membeli dressing siap pakai lagi.","8","2 sendok makan",
["3/4 cangkir mayones","1/2 cangkir krim asam","1/2 sendok teh kucai kering","1/2 sendok teh peterseli kering","1/2 sendok teh daun dill kering","1/4 sendok teh bubuk bawang putih","1/4 sendok teh bubuk bawang bombai","1/8 sendok teh lada hitam bubuk"],
["Masukkan semua bahan ke dalam botol kaca bertutup. Kocok hingga bahan-bahan tercampur rata.","Simpan di lemari es selama 30 menit sebelum disajikan."],
["Gunakan mayones dan krim asam rendah lemak untuk mengurangi lemak dan kalori."],
["3-1/2 lemak"]))
P.append(R(3726,"Taco Lunak dengan Bumbu Meksiko","Banyak hidangan etnis telah menjadi hidangan Amerika, dan penderita penyakit ginjal yang menjalani diet juga ingin menikmati cita rasa unik dari negara lain yang telah mereka sukai. Taco Lunak dengan Bumbu Meksiko adalah resep ramah ginjal yang memungkinkan pasien ginjal tetap memasukkan malam taco dalam menu mingguan mereka.","7","2 taco",
["1 resep Bumbu Meksiko","5 sendok makan bawang bombai","2 cangkir selada","1 pon daging sapi giling","1/2 cangkir saus tomat rendah natrium","14 tortilla tepung, 6 inci","5 sendok makan keju cheddar tajam parut","5 sendok makan krim asam"],
["Buat resep Bumbu Meksiko (di bawah Saus dan Bumbu pada bagian Resep di DaVita.com).","Cincang bawang bombai dan selada.","Tumis daging sapi giling hingga kecokelatan dan tiriskan. Tambahkan campuran bumbu dan saus tomat rendah natrium. Panaskan dengan api sedang. Hangatkan tortilla.","Untuk menyusun taco lunak, ambil 1 tortilla tepung, tambahkan 1/4 cangkir daging sapi giling berbumbu, 1 sendok teh keju, 1 sendok teh bawang bombai, 1 sendok teh krim asam, dan selada sesuai keinginan."],
["Kalkun giling atau pengganti daging giling vegetarian dapat digunakan sebagai pengganti daging sapi giling."],
["2 daging","2 pati","1 sayuran, kalium sedang","1 lemak"]))
P.append(R(3730,"Jambalaya","Malam ini Anda dapat menghadirkan cita rasa ala Kreol New Orleans di meja makan Anda. Ahli gizi DaVita, Brittney, menunjukkan cara \"memberi bumbu pada hidangan\" dengan resep Jambalaya yang lezat dan ramah ginjal.","12","1 cangkir",
["2 cangkir bawang bombai","1 cangkir paprika","2 siung bawang putih","2 cangkir beras putih converted, mentah","1/2 sendok teh lada hitam","8 ons saus tomat kalengan rendah natrium","2 cangkir kaldu sapi rendah natrium","2 pon udang mentah","1/2 cangkir margarin"],
["Panaskan oven terlebih dahulu hingga 350º F.","Cincang bawang bombai, paprika, dan bawang putih. Kupas udang.","Dalam mangkuk besar, campurkan semua bahan kecuali margarin.","Tuang ke dalam loyang 9” x 13” dan ratakan.","Iris margarin dan letakkan di atas bahan-bahan.","Tutup dengan penutup atau foil.","Panggang selama 1 jam 15 menit. Sajikan panas."],
["Beras putih converted Uncle Ben’s® adalah merek yang populer. Beras converted, juga dikenal sebagai beras parboiled, dikukus sebelum digiling kulitnya. Akibatnya butir beras menyerap nutrisi dari kulitnya dan nasi matang lebih cepat.","1 batang mentega atau margarin setara dengan 1/2 cangkir.","Sebagai variasi, cobalah mengganti udang dengan ayam matang potong dadu."],
["2 daging","2 pati","1 sayuran, kalium sedang"]))
P.append(R(3733,"Roti Stroberi","Ahli gizi ginjal DaVita, Gaye dari Tennessee, bercerita bahwa ia memanggang resep ramah ginjal Roti Stroberi dalam loyang aluminium kecil, lalu membungkusnya dengan selofan dan pita untuk membuat hadiah yang kreatif, menyenangkan, dan yang terpenting, lezat.","20","1 iris",
["2-1/2 cangkir stroberi segar atau 14 ons stroberi beku tanpa tambahan gula","3 cangkir tepung terigu putih serbaguna","2 cangkir gula pasir","1 sendok teh soda kue","1/4 sendok teh kayu manis bubuk","3/4 sendok teh garam","4 butir telur besar","1 cangkir minyak kanola"],
["Panaskan oven terlebih dahulu hingga 350° F.","Cincang halus stroberi.","Dalam mangkuk adonan sedang, kocok telur. Tambahkan minyak kanola dan stroberi lalu aduk rata.","Campurkan bahan kering dalam mangkuk adonan besar terpisah.","Buat lubang di tengah bahan kering dan tuang campuran telur.","Gunakan sendok besar dan aduk hingga tercampur rata; jangan terlalu banyak diaduk.","Tuang adonan ke dalam dua loyang roti 9″ x 5″ yang tidak diolesi minyak. Panggang 50 sampai 60 menit.","Dinginkan selama 15 menit, lalu gunakan pisau untuk melepaskan sisi roti dari loyang dan keluarkan dengan hati-hati. Selesaikan pendinginan di atas rak.","Sajikan atau bungkus roti dengan plastik pembungkus atau foil agar tetap segar. Roti dapat disimpan di lemari es atau dibekukan."],
["Periksa apakah roti sudah matang dengan menusukkan tusuk gigi ke bagian tengah. Jika keluar bersih, roti sudah matang.","Penyimpanan di lemari es menjaga rasa stroberi dalam roti tetap lebih segar.","Untuk penderita diabetes, gunakan Splenda® Sugar Blend for Baking sebagai pengganti gula dan produk telur rendah kolesterol sebagai pengganti telur. 1 iris setara dengan 206 kalori, 23 gram karbohidrat, 11 gram lemak, dan 0 mg kolesterol.","2-1/2 cangkir stroberi cincang kira-kira 14 ons."],
["1 pati","1/2 buah, kalium rendah","1/2 kalori tinggi","2 lemak"]))
P.append(R(3734,"Slaw Nanas","Nikmati buah dan sayuran dalam Slaw Nanas yang lezat dari ahli gizi ginjal DaVita, Barbara di Arizona. Ia membuatnya tetap sederhana, sehat, dan ramah ginjal dengan hanya empat bahan yang lezat.","8","1/2 cangkir",
["2-1/2 cangkir kubis hijau, diiris halus","1/2 cangkir wortel, diparut","20 ons nanas cincang kalengan dalam sari buah tanpa pemanis","1/4 cangkir cranberry kering, manis"],
["Iris halus kubis dan parut wortel lalu campurkan dalam mangkuk 2 quart.","Tambahkan nanas cincang beserta sarinya dan cranberry kering ke dalam mangkuk.","Campurkan bahan-bahan slaw dan dinginkan di lemari es minimal 30 menit sebelum disajikan."],
["Iris kubis menjadi potongan seukuran coleslaw menggunakan food processor atau cincang dengan pisau tajam.","2-1/2 cangkir kubis iris kira-kira 3/4 kepala kubis kecil."],
["1 buah, kalium rendah","1/2 sayuran, kalium rendah"]))
P.append(R(3740,"Salad Selada dan Jamur","Lain kali Anda ingin salad yang renyah, cobalah resep ramah ginjal Salad Selada dan Jamur.","4","1 cangkir",
["3 cangkir selada butterhead","1 cangkir jamur iris","1/4 cangkir bawang merah","1/2 cangkir wortel"],
["Cincang bawang merah dan parut wortel.","Campurkan sayuran dalam mangkuk besar dan aduk.","Bagi menjadi 4 porsi dan sajikan dalam mangkuk salad yang didinginkan."],
["Gunakan takaran yang tepat untuk memastikan kandungan kalium tidak terlalu tinggi.","Tambahkan dressing salad rendah natrium favorit Anda."],
["1 sayuran, kalium sedang"]))
P.append(R(3743,"Bola Popcorn Manis","Bola Popcorn Manis adalah sajian menggugah selera yang lezat sepanjang tahun. Nikmati resep ramah ginjal ini sebagai camilan sore yang menggoda atau sebagai pencuci mulut yang nikmat. Bola Popcorn Manis pasti akan menjadi andalan dalam diet ginjal Anda.","18","1 bola popcorn",
["16 cangkir popcorn yang sudah dimasak, tanpa garam","2 cangkir sirup jagung gelap Karo®","2 cangkir gula merah","1 cangkir air","1 sendok makan cuka","4 sendok makan mentega kocok"],
["Masak popcorn dan letakkan dalam mangkuk besar. Sisihkan untuk digunakan nanti.","Campurkan sirup, gula merah, air, dan cuka dalam panci. Masak dengan api sedang sambil terus diaduk hingga campuran mendidih. Lanjutkan memasak dan mengaduk hampir terus-menerus sekitar 15-20 menit dengan api sedang. Masak hingga tahap bola keras (hingga sedikit campuran membentuk bola keras saat diuji dalam air yang sangat dingin.)","Angkat dari api, segera tambahkan mentega, dan aduk.","Tuang campuran perlahan ke atas popcorn dalam mangkuk besar sambil diaduk rata. Bentuk menjadi bola dengan tekanan sesedikit mungkin.","Bungkus setiap bola popcorn dengan plastik pembungkus dan simpan dalam wadah kedap udara."],
["Olesi tangan dengan mentega, atau lebih baik lagi, kenakan sarung tangan karet yang diolesi mentega. Popcorn tidak akan terlalu menempel dan tidak terlalu panas!"],
["1 pati","1 lemak","2 kalori tinggi"]))
P.append(R(3744,"Saus BBQ Putih","Saus BBQ Putih bebas tomat, sehingga rendah kalium dibandingkan saus BBQ tradisional. Bereksperimenlah dengan saus ramah ginjal ini untuk menemukan cara favorit Anda menambah cita rasa.","8","2 sendok makan",
["3/4 cangkir mayones","1/4 cangkir cuka sari apel","2 sendok teh gula","1 sendok teh horseradish","1/8 sendok teh garam","1 sendok teh lada","1-1/2 sendok teh air lemon"],
["Campurkan semua bahan dalam mangkuk dan kocok hingga tercampur.","Simpan di lemari es selama 30 menit agar cita rasanya menyatu."],
["Tambahkan Saus BBQ Putih saat memanggang unggas, daging, atau sayuran; gunakan sebagai marinade atau sajikan sebagai saus pendamping.","Gunakan mayones rendah lemak dan hilangkan 1/8 sendok teh garam jika diinginkan."],
["3 lemak"]))
P.append(R(3747,"Salmon Bakar dengan Kerak Herba","Seperti orang Texas sejati, ahli gizi ginjal DaVita, Elaine dari Texas, menambahkan sedikit bumbu pada resepnya untuk Salmon Bakar dengan Kerak Herba. Oregano, daun ketumbar, daun bawang, bawang putih, air lemon, dan minyak zaitun menciptakan kerak herba yang lezat baik saat hidangan salmon ini disiapkan dalam oven maupun di panggangan.","4","1 fillet",
["12 ons fillet salmon tanpa kulit","1/2 cangkir oregano","1/3 cangkir daun ketumbar","1/4 cangkir daun bawang","1 siung bawang putih","1 sendok makan air lemon","1 sendok makan minyak zaitun","1/4 sendok teh garam","1/4 sendok teh lada hitam"],
["Panaskan oven terlebih dahulu hingga 400° F atau panaskan panggangan.","Menggunakan aluminium foil, buat 1 kantong masak untuk setiap fillet (jika menggunakan salmon beku, pastikan sudah benar-benar mencair).","Cincang oregano, daun ketumbar, daun bawang, dan bawang putih. Campurkan dengan air lemon, minyak zaitun, garam, dan lada dalam food processor. Proses untuk mencincang dan mencampur.","Lumuri fillet salmon dengan campuran herba secara melimpah.","Letakkan setiap fillet dalam kantong foil dan rekatkan.","Letakkan kantong foil di atas loyang datar atau piring panggangan jika memasak di panggangan.","Panggang dalam oven selama 30 menit atau hingga matang, atau bakar selama 6 sampai 8 menit tergantung ketebalan."],
["Gunakan salmon segar atau beku. Jika menggunakan salmon beku, pastikan sudah benar-benar mencair sebelum dimasak.","Salmon dapat dipanggang dalam oven atau dimasak di panggangan.","Sesuaikan ukuran porsi untuk memenuhi target protein Anda."],
["2-1/2 daging","1/2 lemak"]))
P.append(R(3749,"Ayam Bawang Putih dengan Cuka Balsamic","Ahli gizi ginjal DaVita selalu mencari hidangan sederhana dengan cita rasa gourmet dan gizi yang baik untuk pasien cuci darah mereka. Carrie dari Texas menemukan pemenangnya ketika ia menemukan Ayam Bawang Putih dengan Cuka Balsamic yang ramah ginjal. Nikmati cita rasa kaya bawang putih dan cuka balsamic yang berpadu sehingga ayam terasa seperti berasal dari restoran favorit Anda.","4","1 dada ayam",
["4 dada ayam tanpa tulang dan tanpa kulit","1 sendok teh lada hitam segar giling","1 sendok makan minyak zaitun","8 siung bawang putih, dikupas","3/4 cangkir jamur kancing putih, diiris","1/4 cangkir cuka balsamic","3/4 cangkir kaldu ayam rendah natrium","1 lembar daun salam","1/4 sendok teh daun thyme","1 sendok makan tepung maizena"],
["Cuci dan buang kelebihan lemak dari dada ayam.","Lumuri kedua sisi dada ayam dengan lada.","Panaskan minyak zaitun dalam wajan antilengket dengan api sedang-besar, dan masak hingga kecokelatan merata di satu sisi (sekitar 3 menit).","Tambahkan bawang putih, balik ayam, dan tebarkan jamur di seluruh permukaan.","Gerakkan ayam dan jamur agar tidak lengket dan masak sekitar 3 menit.","Dalam mangkuk kecil, campurkan cuka balsamic, kaldu ayam rendah natrium, daun salam, daun thyme, dan tepung maizena.","Tambahkan campuran ke wajan berisi ayam. Aduk hingga saus mengental.","Tutup dan masak dengan api sedang-kecil sekitar 10 menit.","Buang daun salam dan bawang putih sebelum disajikan. Sajikan di atas nasi atau pasta."],
["Jika Anda menjalani diet protein yang lebih rendah, cobalah resep ini tetapi kurangi porsinya sesuai rencana diet Anda.","Simpan sisa ayam di lemari es untuk digunakan dalam salad atau sandwich keesokan harinya."],
["4 daging","1/2 sayuran, kalium rendah"]))
P.append(R(3750,"Slaw Udang Pulau","Eileen, ahli gizi ginjal DaVita dari New York, membagikan cita rasa tropis dengan resep ramah ginjalnya, Slaw Udang Pulau. Ini adalah kombinasi sempurna antara slaw tradisional yang renyah dengan udang gurih dan pedas.","8","3/4 cangkir",
["12 ons udang matang beku, dikupas dan dibuang urat","6 cangkir campuran coleslaw kemasan","1/4 cangkir bawang bombai, dicincang","2 cangkir paprika kuning, dicincang","1/4 cangkir daun ketumbar segar, dicincang","1/4 sendok teh cabai cayenne","1/2 cangkir mayones","1/2 cangkir krim asam","1 sendok makan air lemon","1 sendok teh bumbu Italia"],
["Cincang bawang bombai, paprika, dan daun ketumbar.","Cairkan udang dan keringkan.","Dalam mangkuk besar, campurkan udang, campuran coleslaw, bawang bombai, paprika, daun ketumbar, dan 1/8 sendok teh cabai cayenne.","Dalam mangkuk kecil, campurkan mayones, krim asam, air lemon, bumbu Italia, dan sisa 1/8 sendok teh cabai cayenne. Tuang dressing ke atas campuran udang dan kubis lalu aduk rata.","Dinginkan selama 2 jam dan sajikan."],
["Jika semua bahan didinginkan sebelum persiapan, waktu pendinginan 2 jam dapat dilewati.","Jika Anda ingin “menambah level kepedasan”, tambahkan lebih banyak cabai cayenne sesuai selera.","Untuk variasi dan sentuhan manis, tambahkan 1/2 cangkir potongan kecil nanas."],
["1 daging","1-1/2 sayuran, kalium rendah","2 lemak"]))
P.append(R(3751,"Ayam dengan Apel, Wortel, dan Biji-bijian","Jika Anda mencari cara untuk menambahkan biji-bijian utuh ke dalam diet ginjal Anda, inilah resep yang patut dicoba. Ahli gizi DaVita, Deanna dari Michigan, menciptakan Ayam dengan Apel, Wortel, dan Biji-bijian untuk dibagikan kepada pasien cuci darahnya. Rendah natrium, kalium, dan fosfor serta tinggi serat dan cita rasa.","6","1-3/4 cangkir",
["1 bawang bombai kecil","2 wortel besar","2 apel sedang","1 sendok teh kayu manis bubuk","1 sendok teh ketumbar bubuk","1 sendok teh jinten bubuk","1/4 sendok teh lada hitam","1 pon dada ayam","2 sendok makan minyak zaitun","15 ons kaldu ayam rendah natrium","1 sachet Seeds of Change® Quinoa and Brown Rice","3/4 cangkir cranberry kering"],
["Kupas, bilas, dan potong dadu bawang bombai dan wortel. Buang bagian tengah apel dan potong dadu.","Dalam mangkuk kecil, campurkan kayu manis, ketumbar, jinten, dan lada.","Keringkan ayam dengan tisu dapur. Potong menjadi bentuk kubus dan lumuri potongan dengan campuran rempah.","Dalam wajan besar dengan api sedang-besar tambahkan 1 sendok makan minyak. Masukkan bawang bombai, wortel, dan apel. Masak sambil sesekali diaduk hingga sayuran mulai kecokelatan, sekitar 15 menit. Pindahkan ke mangkuk sedang.","Tambahkan sisa satu sendok makan minyak ke wajan. Cokelatkan ayam selama 2 sampai 4 menit per sisi. Tambahkan kaldu dan sachet quinoa dan beras merah. Didihkan perlahan. Masak selama 15 sampai 25 menit.","Tambahkan cranberry kering dan campuran sayuran/buah. Masak hingga cairan hampir habis, 5 sampai 10 menit."],
["Beras merah dan quinoa bebas gluten. Jika Anda menderita penyakit celiac, resep ini adalah pilihan yang baik.","Beras merah dan quinoa adalah sumber serat dan biji-bijian utuh yang baik."],
["2 daging","1 pati","1/2 sayuran, kalium rendah","1 buah, kalium rendah","1 kalori tinggi"]))
save(5,P)
